Rules.InvariantScript:
With(
    {
        t: Coalesce(CountRows(cmpProgressRail.ResolvedSteps), 0),
        d: Coalesce(CountRows(Filter(cmpProgressRail.ResolvedSteps, CountsAsDone)), 0)
    },
    RoundDown(d / Max(t, 1) * 100, 0)
)

ForAll(
    Sort(cmpProgressRail.Steps, Order) As s,
    With(
        {
            hit: Filter(
                cmpProgressRail.StateMap,
                Lower(State) = Lower(Coalesce(s.State, ""))
            )
        },
        With(
            {
                m: If(
                    CountRows(hit) > 0,
                    First(hit),
                    LookUp(cmpProgressRail.StateMap, Lower(State) = "default")
                )
            },
            {
                Order: s.Order,
                Title: s.Title,
                State: s.State,
                Label: If(IsBlank(s.Detail), m.Label, s.Detail),
                NodeColor: m.NodeColor,
                TrackColor: m.TrackColor,
                TrackFill: m.TrackFill,
                Emphasize: m.Emphasize,
                CountsAsDone: m.CountsAsDone,
                IsCurrent: m.IsCurrent
            }
        )
    )
)

Table(
    { Order: 1, Title: "Submitted", State: "done",     Detail: "" },
    { Order: 2, Title: "Review",    State: "current",  Detail: "" },
    { Order: 3, Title: "Approval",  State: "upcoming", Detail: "" }
)
